input.query:
PREFIX schema: <https://schema.org/> PREFIX aw: <https://w3id.org/agentweb-testbed#>
SELECT ?name ?pname ?rate ?apr ?term ?type ?pts ?pay ?close ?amt WHERE {
?p a schema:MortgageLoan; schema:name ?name; schema:provider ?pr; schema:interestRate ?rate; schema:annualPercentageRate ?apr; schema:loanTerm ?t; aw:rateType ?type.
?pr schema:name ?pname. ?t schema:value ?term.
OPTIONAL{?p aw:discountPoints ?pts}
OPTIONAL{?p aw:estimatedMonthlyPayment ?m. ?m schema:value ?pay}
OPTIONAL{?p aw:estimatedClosingCosts ?c. ?c schema:value ?close}
OPTIONAL{?p aw:exampleLoanAmount ?a. ?a schema:value ?amt}
} ORDER BY ?rate

